import org.eclipse.rdf4j.query.algebra.helpers.FilterBindingScope;
import org.eclipse.rdf4j.query.algebra.helpers.TupleExprs;
import org.eclipse.rdf4j.query.impl.EmptyBindingSet;
import org.junit.jupiter.api.Test;

/** The public SERVICE backend sees invocation constraints beyond traversed local tuple Vars. */
class ServiceObservationBoundaryTest {
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI ENDPOINT = VF.createIRI("urn:observation:service");
	private static final IRI ALLOWED = VF.createIRI("urn:observation:allowed");
	private static final String INPUT = "remoteConstraint";

	@Test
	void actualServiceBackendReceivesNonTraversedInvocationConstraints() {
		Service service = service();
		List<BindingSet> observed = new ArrayList<>();
		FederatedService backend = backend(observed);
		ServiceQueryEvaluationStep step = new ServiceQueryEvaluationStep(service, service.getServiceRef(),
				endpoint -> backend);
		assertThat(hasResult(step, input(ALLOWED))).isTrue();
		assertThat(hasResult(step, input(VF.createIRI("urn:observation:rejected")))).isFalse();
		assertThat(hasResult(step, EmptyBindingSet.getInstance())).isFalse();
		assertThat(observed).hasSize(3);
		assertThat(observed.get(0).getValue(INPUT)).isEqualTo(ALLOWED);
		assertThat(observed.get(1).getValue(INPUT)).isEqualTo(VF.createIRI("urn:observation:rejected"));
		assertThat(observed.get(2).hasBinding(INPUT)).isFalse();
		assertThat(service.getServiceExpr().getBindingNames()).doesNotContain(INPUT);
	}

	@Test
	void serviceCannotCertifyACompleteInputDomainFromItsTraversedModelAlone() {
		Filter filter = new Filter(new SingletonSet(), new Exists(service()));
		filter.setConditionBindingScope(ConditionBindingScope.retain(Set.of()));
		assertThat(TupleExprs.conditionBindingDomain(filter.getCondition()).known())
				.as("SERVICE has executable serialized syntax and a public backend receiving additional constraints")
				.isFalse();
		assertThat(FilterBindingScope.allowsAllConditionBindings(filter)).isFalse();
		filter.setConditionBindingScope(ConditionBindingScope.ALL);
		assertThat(FilterBindingScope.allowsAllConditionBindings(filter)).isTrue();
	}

	@Test
	void explicitFilterFrameControlsWhatTheActualServiceBackendCanObserve() {
		List<BindingSet> observed = new ArrayList<>();
		FederatedService backend = backend(observed);
		BindingSetAssignment input = new BindingSetAssignment();
		input.setBindingSets(List.of(input(ALLOWED)));
		Filter filter = new Filter(input, new Exists(service()));
		filter.setConditionBindingScope(ConditionBindingScope.retain(Set.of()));
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(new EmptyTripleSource(),
				endpoint -> backend);
		strategy.setQueryExecutionPolicy(QueryExecutionPolicy.DEFAULT);
		try (var rows = strategy.precompile(filter.clone()).evaluate(EmptyBindingSet.getInstance())) {
			assertThat(rows.hasNext()).isFalse();
		}
		assertThat(observed).hasSize(1);
		assertThat(observed.getFirst().hasBinding(INPUT)).isFalse();
		filter.setConditionBindingScope(ConditionBindingScope.ALL);
		try (var rows = strategy.precompile(filter.clone()).evaluate(EmptyBindingSet.getInstance())) {
			assertThat(rows.hasNext()).isTrue();
			assertThat(rows.next().getValue(INPUT)).isEqualTo(ALLOWED);
			assertThat(rows.hasNext()).isFalse();
		}
		assertThat(observed).hasSize(2);
		assertThat(observed.getLast().getValue(INPUT)).isEqualTo(ALLOWED);
	}

	private static Service service() {
		// Service has a separate executable query-string field. The public backend evaluates that remote FILTER;
		// a complete local binding-name proof must not assume the tuple preview is the backend's entire contract.
		return new Service(Var.of("endpoint", ENDPOINT), new SingletonSet(),
				"FILTER(?" + INPUT + " = <" + ALLOWED.stringValue() + ">)", Map.of(), null, false);
	}

	private static FederatedService backend(List<BindingSet> observed) {
		FederatedService backend = mock(FederatedService.class);
		when(backend.ask(any(), any(), any())).thenAnswer(call -> {
			BindingSet input = call.getArgument(1);
			observed.add(new QueryBindingSet(input));
			return ALLOWED.equals(input.getValue(INPUT));
		});
		return backend;
	}

	private static QueryBindingSet input(IRI value) {
		QueryBindingSet input = new QueryBindingSet();
		input.addBinding(INPUT, value);
		return input;
	}

	private static boolean hasResult(ServiceQueryEvaluationStep step, BindingSet input) {
		try (var rows = step.evaluate(input)) {
			return rows.hasNext();
		}
	}
}
